CREATE TABLE IF NOT EXISTS schema_versions(version integer PRIMARY KEY, checksum text NOT NULL, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS settings(key text PRIMARY KEY, value jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS users(id text PRIMARY KEY, username text NOT NULL UNIQUE, name text NOT NULL, password_hash text NOT NULL, totp bytea NOT NULL, last_totp bigint NOT NULL DEFAULT -1, admin boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT false, recovery_hashes text[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS enrollments(hash text PRIMARY KEY, user_id text REFERENCES users(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL, payload bytea);
CREATE TABLE IF NOT EXISTS sessions(hash text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, csrf text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), seen_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS login_limits(key text PRIMARY KEY, attempts integer NOT NULL DEFAULT 0, window_start timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS employees(id text PRIMARY KEY, name text NOT NULL, daily_minutes integer NOT NULL CHECK(daily_minutes BETWEEN 0 AND 1440), user_id text UNIQUE REFERENCES users(id), provider text NOT NULL DEFAULT '', external_id text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS calendars(id text PRIMARY KEY, year integer NOT NULL CHECK(year BETWEEN 2000 AND 2200), title text NOT NULL, source text NOT NULL, checksum text NOT NULL, days jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS projects(id text PRIMARY KEY, title text NOT NULL, brief text NOT NULL DEFAULT '', start_date date NOT NULL, duration_mode text NOT NULL CHECK(duration_mode IN ('working','calendar')), calendar_id text NOT NULL REFERENCES calendars(id), revision bigint NOT NULL DEFAULT 0, external_reference text NOT NULL DEFAULT '', archived_at timestamptz);
CREATE TABLE IF NOT EXISTS memberships(project_id text REFERENCES projects(id) ON DELETE CASCADE, user_id text REFERENCES users(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('manager','member','viewer')), PRIMARY KEY(project_id,user_id));
CREATE TABLE IF NOT EXISTS participation(project_id text REFERENCES projects(id) ON DELETE CASCADE, employee_id text REFERENCES employees(id), weekdays integer[] NOT NULL, window_start text NOT NULL, window_end text NOT NULL, exceptions jsonb NOT NULL DEFAULT '{}', PRIMARY KEY(project_id,employee_id));
CREATE TABLE IF NOT EXISTS tasks(project_id text REFERENCES projects(id) ON DELETE CASCADE, id text NOT NULL, parent_id text, title text NOT NULL, description text NOT NULL DEFAULT '', result text NOT NULL DEFAULT '', brief text NOT NULL DEFAULT '', status text NOT NULL CHECK(status IN ('todo','doing','done')), requested_start date, start_date date, end_date date, planned_minutes integer NOT NULL DEFAULT 0 CHECK(planned_minutes BETWEEN 0 AND 60000000), responsibility text NOT NULL DEFAULT 'internal' CHECK(responsibility IN ('internal','customer')), customer_owner text NOT NULL DEFAULT '', customer_due date, owner_legacy text NOT NULL DEFAULT '', legacy_start date, legacy_end date, legacy_actual_minutes integer NOT NULL DEFAULT 0 CHECK(legacy_actual_minutes>=0), sort_order integer NOT NULL DEFAULT 0, PRIMARY KEY(project_id,id), FOREIGN KEY(project_id,parent_id) REFERENCES tasks(project_id,id) DEFERRABLE INITIALLY DEFERRED, CHECK(end_date IS NULL OR start_date IS NULL OR end_date>=start_date));
CREATE TABLE IF NOT EXISTS dependencies(project_id text NOT NULL, predecessor text NOT NULL, successor text NOT NULL, mode text NOT NULL CHECK(mode IN ('together','after','delay')), lag_days integer NOT NULL CHECK(lag_days BETWEEN 0 AND 3650), PRIMARY KEY(project_id,predecessor,successor), FOREIGN KEY(project_id,predecessor) REFERENCES tasks(project_id,id) ON DELETE CASCADE, FOREIGN KEY(project_id,successor) REFERENCES tasks(project_id,id) ON DELETE CASCADE, CHECK(predecessor<>successor));
CREATE TABLE IF NOT EXISTS assignments(project_id text NOT NULL, task_id text NOT NULL, employee_id text REFERENCES employees(id), daily_minutes integer NOT NULL CHECK(daily_minutes BETWEEN 1 AND 1440), PRIMARY KEY(project_id,task_id,employee_id), FOREIGN KEY(project_id,task_id) REFERENCES tasks(project_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS time_entries(id text PRIMARY KEY, project_id text NOT NULL, task_id text NOT NULL, employee_id text REFERENCES employees(id), work_date date NOT NULL, minutes integer NOT NULL CHECK(minutes BETWEEN 1 AND 1440), comment text NOT NULL DEFAULT '', actor text REFERENCES users(id), FOREIGN KEY(project_id,task_id) REFERENCES tasks(project_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS snapshots(project_id text REFERENCES projects(id) ON DELETE CASCADE, revision bigint NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(project_id,revision));
CREATE TABLE IF NOT EXISTS audit(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, actor text, project_id text, action text NOT NULL, details jsonb NOT NULL DEFAULT '{}', request_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS api_tokens(hash text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), name text NOT NULL, project_ids text[] NOT NULL, scopes text[] NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outbox(id text PRIMARY KEY, project_id text, provider text NOT NULL, generation bigint NOT NULL DEFAULT 0, payload jsonb NOT NULL, state text NOT NULL DEFAULT 'paused', attempts integer NOT NULL DEFAULT 0, ready_at timestamptz NOT NULL DEFAULT now(), leased_until timestamptz, last_error text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS event_mappings(operation_id text PRIMARY KEY, provider text NOT NULL, remote_id text NOT NULL, etag text NOT NULL DEFAULT '', payload_hash text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_project_time ON audit(project_id,created_at DESC);
CREATE INDEX IF NOT EXISTS outbox_ready ON outbox(state,ready_at);
